// Non-primary locales fall back to the complete English Evolution namespace
// until product copy is reviewed for those markets — except the release201/28
// `studio.v2` namespace, which ships reviewed de/fr/es copy.
//
// We shallow-merge so everything (except `studio.v2`) still references the same
// English objects, but each locale's `studio` gets its own `v2` subtree.
const enStudio = evolutionMessages.en.studio as Record<string, unknown>;
function studioWithV2(v2: MessageTree): MessageTree {
  return { ...enStudio, v2 } as MessageTree;
}

